"""Source-gated bicycle and rack spawn with Native readback and cleanup."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from native_geometry import RACK_ENVELOPE_XY_M


def read_asset_inventory(path: Path, expected_sha256: str) -> dict:
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("Native blueprint inventory hash mismatch")
    inventory = json.loads(raw)
    if inventory.get("source_kind") != "original_local_native_blueprint_inventory" or not inventory.get("world_map"):
        raise ValueError("Native blueprint inventory source unverified")
    if not isinstance(inventory.get("blueprint_ids"), list):
        raise ValueError("Native blueprint inventory lacks IDs")
    return inventory


def _blueprint(library, blueprint_id):
    try:
        blueprint = library.find(blueprint_id)
    except (KeyError, RuntimeError) as exc:
        raise ValueError("Native blueprint unavailable: " + blueprint_id) from exc
    if blueprint is None or blueprint.id != blueprint_id:
        raise ValueError("Native blueprint unavailable: " + blueprint_id)
    return blueprint


def _vertices_xy(actor):
    body = actor.bounding_box.get_world_vertices(actor.get_transform())
    if len(body) != 8:
        raise ValueError("Native actor body readback incomplete")
    return [(float(v.x), float(v.y)) for v in body]


def spawn_bicycle_and_rack(world, carla, scene: dict, inventory: dict):
    """Spawn actual assets, verify body and type, destroy both on any failure."""
    bicycle_id = scene.get("bicycle_blueprint_id")
    rack_id = scene.get("rack_blueprint_id")
    if not bicycle_id or not rack_id or bicycle_id == rack_id:
        raise ValueError("distinct bicycle and rack blueprint IDs required")
    if inventory.get("source_kind") != "original_local_native_blueprint_inventory" or not set((bicycle_id, rack_id)) <= set(inventory.get("blueprint_ids", [])):
        raise ValueError("source-gated bicycle/rack inventory missing assets")
    library = world.get_blueprint_library()
    actors = []
    try:
        bicycle_bp = _blueprint(library, bicycle_id)
        rack_bp = _blueprint(library, rack_id)
        bicycle = world.spawn_actor(bicycle_bp, carla.Transform(carla.Location(x=-30., y=-.75, z=.25), carla.Rotation(yaw=0.)))
        if bicycle is None:
            raise RuntimeError("Native bicycle spawn failed")
        actors.append(bicycle)
        rack = world.spawn_actor(rack_bp, carla.Transform(carla.Location(x=0., y=2.3, z=0.), carla.Rotation(yaw=0.)))
        if rack is None:
            raise RuntimeError("Native rack spawn failed")
        actors.append(rack)
        if bicycle.type_id != bicycle_id or rack.type_id != rack_id:
            raise ValueError("Native actor type readback mismatch")
        bicycle_body = _vertices_xy(bicycle)
        rack_body = _vertices_xy(rack)
        if max(abs(y + .75) for _, y in bicycle_body) >= 1.25:
            raise ValueError("Native bicycle body outside alley route")
        x0, y0, x1, y1 = RACK_ENVELOPE_XY_M
        if not all(x0 <= x <= x1 and y0 <= y <= y1 for x, y in rack_body):
            raise ValueError("Native rack body outside reviewed envelope")
        return bicycle, rack, actors
    except BaseException:
        for actor in reversed(actors):
            actor.destroy()
        raise

"""Source-bound bicycle speed and contemporaneous-condition measurements.

This is a saved-data checker. It does not decide what speed is prudent.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


REQUIRED_CONTEXT = ("jurisdiction", "bicycle_classification", "alley_route", "rack_geometry")
REQUIRED_CONDITIONS = ("weather", "surface", "visibility", "pedestrians", "curvature")


def _read_source(root: Path, entry: dict) -> dict:
    rel = Path(entry["path"])
    if rel.is_absolute() or ".." in rel.parts:
        raise ValueError("source path must stay within acquisition")
    source = (root / rel).resolve()
    if not source.is_relative_to(root.resolve()) or not source.is_file():
        raise ValueError("missing required source: " + str(rel))
    data = source.read_bytes()
    if hashlib.sha256(data).hexdigest() != entry["sha256"]:
        raise ValueError("stale required source: " + str(rel))
    return json.loads(data)


def measure(root: Path, inventory: dict, expected_case_id: str) -> dict:
    """Check source joins and retain all measured samples, without a verdict."""
    if inventory.get("case_id") != expected_case_id:
        raise ValueError("case identity mismatch")
    if inventory.get("source_kind") != "original_native":
        raise ValueError("source is not original Native acquisition")
    sources = inventory.get("sources", {})
    if set(sources) != {"frame_map", "bicycle_motion", "context"}:
        raise ValueError("missing required source inventory")
    frame_map = _read_source(root, sources["frame_map"])
    motion = _read_source(root, sources["bicycle_motion"])
    context = _read_source(root, sources["context"])
    if motion.get("case_id") != expected_case_id or context.get("case_id") != expected_case_id:
        raise ValueError("source case identity mismatch")
    frames = frame_map.get("frames")
    samples = motion.get("samples")
    if not isinstance(frames, list) or len(frames) < 2 or not isinstance(samples, list) or len(samples) != len(frames):
        raise ValueError("incomplete synchronized frame history")
    frame_ids = [row.get("frame") for row in frames]
    times = [row.get("time_s") for row in frames]
    if any(not isinstance(f, int) for f in frame_ids) or frame_ids != list(range(frame_ids[0], frame_ids[0] + len(frames))):
        raise ValueError("nonconsecutive original frame map")
    if any(not isinstance(t, (int, float)) or not math.isfinite(t) for t in times) or any(b <= a for a, b in zip(times, times[1:])):
        raise ValueError("nonmonotonic original time")
    if any(k not in context for k in REQUIRED_CONTEXT):
        raise ValueError("missing contemporaneous context")
    classification = context["bicycle_classification"]
    if classification.get("human_powered") is not True or classification.get("moped") is not False or not classification.get("source"):
        raise ValueError("bicycle classification unresolved")
    if context["jurisdiction"].get("city_of_las_vegas") is not True or not context["jurisdiction"].get("source"):
        raise ValueError("municipal jurisdiction unresolved")
    if not context["alley_route"].get("source") or not context["rack_geometry"].get("source"):
        raise ValueError("alley or rack construction unbound")
    conditions = context.get("samples")
    if not isinstance(conditions, list) or len(conditions) != len(frames):
        raise ValueError("missing contemporaneous condition history")
    for frame, t, row in zip(frame_ids, times, conditions):
        if row.get("frame") != frame or row.get("time_s") != t:
            raise ValueError("condition/frame time join mismatch")
        if any(key not in row for key in REQUIRED_CONDITIONS):
            raise ValueError("missing contemporaneous condition")
    output = []
    for frame, t, sample in zip(frame_ids, times, samples):
        if sample.get("frame") != frame or sample.get("time_s") != t:
            raise ValueError("motion/frame time join mismatch")
        velocity = sample.get("velocity_mps")
        if not isinstance(velocity, list) or len(velocity) != 3 or any(not isinstance(x, (int, float)) or not math.isfinite(x) for x in velocity):
            raise ValueError("missing finite bicycle velocity")
        output.append({"frame": frame, "time_s": t, "speed_mps": math.sqrt(sum(x * x for x in velocity))})
    return {
        "format": "c10307-bicycle-speed-measurement",
        "case_id": expected_case_id,
        "source_kind": "original_native",
        "sources": sources,
        "samples": output,
        "context": {key: context[key] for key in REQUIRED_CONTEXT},
        "condition_samples": conditions,
        "summary": {"sample_count": len(output), "mean_speed_mps": sum(row["speed_mps"] for row in output) / len(output), "maximum_speed_mps": max(row["speed_mps"] for row in output)},
        "legal_prudence": "unresolved",
    }


def main():
    import argparse
    p = argparse.ArgumentParser()
    p.add_argument("--root", type=Path, required=True)
    p.add_argument("--inventory", type=Path, required=True)
    p.add_argument("--case", required=True)
    p.add_argument("--output", type=Path, required=True)
    args = p.parse_args()
    result = measure(args.root, json.loads(args.inventory.read_text()), args.case)
    if args.output.exists():
        raise ValueError("refusing to overwrite saved measurement")
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")


if __name__ == "__main__":
    main()

"""Independent measurement comparison; never labels legal prudence."""
from __future__ import annotations

import json
from pathlib import Path


VARIABLE = {
    "speed_under_clear_conditions": "speed",
    "visibility_at_reference_speed": "visibility",
    "pedestrian_at_reference_speed": "pedestrians",
    "surface_at_reference_speed": "surface",
}


def audit(plan: dict, comparison_id: str, left: dict, right: dict) -> dict:
    comparison = next((row for row in plan["comparisons"] if row["comparison_id"] == comparison_id), None)
    if comparison is None or comparison_id not in VARIABLE:
        raise ValueError("unknown comparison")
    if [left.get("case_id"), right.get("case_id")] != comparison["case_ids"]:
        raise ValueError("comparison case identity mismatch")
    for record in (left, right):
        if record.get("source_kind") != "original_native" or record.get("legal_prudence") != "unresolved":
            raise ValueError("missing original measurement or judgment separation")
        if not record.get("samples") or any("speed_mps" not in row for row in record["samples"]):
            raise ValueError("missing speed history")
    variable = VARIABLE[comparison_id]
    context_fields = ("jurisdiction", "bicycle_classification", "alley_route", "rack_geometry")
    for field in context_fields:
        if field == variable:
            continue
        if left["context"].get(field) != right["context"].get(field):
            raise ValueError("fixed condition changed: " + field)
    if variable == "speed":
        a, b = left["summary"]["mean_speed_mps"], right["summary"]["mean_speed_mps"]
        if a == b:
            raise ValueError("measured speed did not differ")
    condition_fields = ("weather", "surface", "visibility", "pedestrians", "curvature")
    for field in condition_fields:
        if field != variable and [row[field] for row in left["condition_samples"]] != [row[field] for row in right["condition_samples"]]:
            raise ValueError("fixed condition changed: " + field)
    if variable != "speed" and [row[variable] for row in left["condition_samples"]] == [row[variable] for row in right["condition_samples"]]:
        raise ValueError("declared condition did not differ: " + variable)
    if len(left["samples"]) != len(right["samples"]) or [row["time_s"] for row in left["samples"]] != [row["time_s"] for row in right["samples"]]:
        raise ValueError("comparison frame/time coverage differs")
    if len(left["condition_samples"]) != len(left["samples"]) or len(right["condition_samples"]) != len(right["samples"]):
        raise ValueError("incomplete condition history")
    return {"format": "c10307-bicycle-speed-comparison-audit", "comparison_id": comparison_id,
            "case_ids": comparison["case_ids"], "passed": True, "deliberate_variable": variable,
            "legal_prudence": "unresolved", "source_kind": "original_native"}


def main():
    import argparse
    p = argparse.ArgumentParser()
    p.add_argument("--plan", type=Path, required=True)
    p.add_argument("--comparison", required=True)
    p.add_argument("--left", type=Path, required=True)
    p.add_argument("--right", type=Path, required=True)
    args = p.parse_args()
    print(json.dumps(audit(json.loads(args.plan.read_text()), args.comparison,
                           json.loads(args.left.read_text()), json.loads(args.right.read_text()))))


if __name__ == "__main__":
    main()

